Here's how to save and restore draft text using Window lifecycle events:

**App.xaml.cs** — Override `CreateWindow` and hook `Stopped`/`Resumed`/`Destroying`:

```csharp
public partial class App : Application
{
    protected override Window CreateWindow(IActivationState? activationState)
    {
        var window = base.CreateWindow(activationState);

        window.Stopped += (s, e) =>
            Preferences.Set("draft_text", GetDraftText());

        window.Resumed += (s, e) =>
            RestoreDraftText(Preferences.Get("draft_text", string.Empty));

        // Android back-button can skip Stopped entirely
        window.Destroying += (s, e) =>
            Preferences.Set("draft_text", GetDraftText());

        return window;
    }

    private string GetDraftText()
    {
        if (Windows[0].Page is AppShell shell
            && shell.CurrentPage is NotePage page)
            return page.ViewModel.DraftText;
        return string.Empty;
    }

    private void RestoreDraftText(string text)
    {
        if (Windows[0].Page is AppShell shell
            && shell.CurrentPage is NotePage page)
            page.ViewModel.DraftText = text;
    }
}
```

**Or cleaner — use a custom Window subclass with a ViewModel reference:**

```csharp
public class AppWindow : Window
{
    private readonly NoteViewModel _vm;

    public AppWindow(Page page, NoteViewModel vm) : base(page) => _vm = vm;

    protected override void OnStopped()
    {
        base.OnStopped();
        Preferences.Set("draft_text", _vm.DraftText);
    }

    protected override void OnResumed()
    {
        base.OnResumed();
        _vm.DraftText = Preferences.Get("draft_text", string.Empty);
    }

    protected override void OnDestroying()
    {
        base.OnDestroying();
        Preferences.Set("draft_text", _vm.DraftText);
    }
}
```

**Key points:**

| Concern | Guidance |
|---------|----------|
| **Where to save** | `OnStopped` — fires when app is no longer visible |
| **Where to restore** | `OnResumed` — fires when returning from background |
| **Android edge case** | Also save in `OnDestroying` (back button skips Stopped) |
| **Performance** | `Preferences` is fast enough; avoid DB writes in lifecycle handlers |
| **First launch** | `Resumed` doesn't fire initially — load saved draft in your page's `OnAppearing` or constructor |

`Preferences.Set`/`Get` uses `SharedPreferences` on Android and `NSUserDefaults` on iOS, so the draft survives even if the OS terminates your app while stopped.
